#include <print>
#include <ranges>
#include <vector>

int main() {
    std::vector<int> nums = {5, 2, 8, 1, 9, 3, 7, 4, 6, 10};

    for (int v : nums | std::views::filter([](int x) { return x > 5; }))
        std::print("{} ", v);
    std::println("");

    std::vector<int> even;
    for (int v : nums) {
        if (v % 2 == 0) even.push_back(v);
    }
    for (int v : even) std::print("{} ", v);
    std::println("");
    return 0;
}

